create extension if not exists postgis;
create extension if not exists pgcrypto;
create type public.report_status as enum ('pending','verified','resolved','possible_duplicate','rejected');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text check(char_length(display_name)<=80),role text not null default 'user' check(role in('user','moderator','authority','admin')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.user_preferences(user_id uuid primary key references auth.users(id) on delete cascade,avoid_isolated boolean not null default true,prefer_main_roads boolean not null default true,prefer_well_lit boolean not null default true,near_transit boolean not null default false,avoid_underpasses boolean not null default false,prefer_busy_areas boolean not null default true,max_extra_minutes smallint not null default 15 check(max_extra_minutes between 0 and 120),updated_at timestamptz not null default now());
create table public.trusted_contacts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null check(char_length(name) between 1 and 80),phone_encrypted text,email_encrypted text,created_at timestamptz not null default now());
create table public.incidents(id uuid primary key default gen_random_uuid(),category text not null,severity smallint not null check(severity between 1 and 5),occurred_at timestamptz not null,location geography(point,4326) not null,source text not null,source_reliability numeric(4,3) not null check(source_reliability between 0 and 1),created_at timestamptz not null default now());
create index incidents_location_gix on public.incidents using gist(location);create index incidents_time_idx on public.incidents(occurred_at desc);
create table public.citizen_reports(id uuid primary key default gen_random_uuid(),reporter_id uuid references auth.users(id) on delete set null,category text not null,severity smallint not null check(severity between 1 and 5),description text check(char_length(description)<=500),occurred_at timestamptz not null,location geography(point,4326) not null,status public.report_status not null default 'pending',reliability_score smallint not null default 35 check(reliability_score between 0 and 100),duplicate_of uuid references public.citizen_reports(id),created_at timestamptz not null default now());
create index reports_location_gix on public.citizen_reports using gist(location);create index reports_time_idx on public.citizen_reports(occurred_at desc);
create table public.report_verifications(id uuid primary key default gen_random_uuid(),report_id uuid not null references public.citizen_reports(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,verdict text not null check(verdict in('still_relevant','no_longer_present','duplicate_inaccurate')),created_at timestamptz not null default now(),unique(report_id,user_id));
create table public.safe_places(id uuid primary key default gen_random_uuid(),name text not null,category text not null check(category in('police','hospital','transport_hub','petrol_station','verified_public_place')),location geography(point,4326) not null,verified_at timestamptz,source text not null,created_at timestamptz not null default now());create index safe_places_location_gix on public.safe_places using gist(location);
create table public.hotspots(id uuid primary key default gen_random_uuid(),center geography(point,4326) not null,radius_m integer not null check(radius_m between 25 and 5000),risk_level numeric(4,3) not null check(risk_level between 0 and 1),window_start timestamptz not null,window_end timestamptz not null,confidence smallint not null check(confidence between 0 and 100),generated_at timestamptz not null default now());create index hotspots_center_gix on public.hotspots using gist(center);
create table public.active_trips(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,status text not null default 'active' check(status in('active','completed','cancelled')),route_summary jsonb not null,expected_arrival timestamptz not null,check_in_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now());
create table public.trip_shares(id uuid primary key default gen_random_uuid(),trip_id uuid not null references public.active_trips(id) on delete cascade,token_hash text not null unique,expires_at timestamptz not null,revoked_at timestamptz,created_at timestamptz not null default now(),check(expires_at>created_at));
alter table public.profiles enable row level security;alter table public.user_preferences enable row level security;alter table public.trusted_contacts enable row level security;alter table public.citizen_reports enable row level security;alter table public.report_verifications enable row level security;alter table public.active_trips enable row level security;alter table public.trip_shares enable row level security;
create policy profiles_own on public.profiles for all using(auth.uid()=id) with check(auth.uid()=id);create policy prefs_own on public.user_preferences for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy contacts_own on public.trusted_contacts for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy reports_public_read on public.citizen_reports for select using(status in('verified','resolved'));create policy reports_create on public.citizen_reports for insert with check(reporter_id is null or auth.uid()=reporter_id);create policy reports_own on public.citizen_reports for select using(auth.uid()=reporter_id);create policy verification_own on public.report_verifications for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy trips_own on public.active_trips for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy shares_via_trip on public.trip_shares for all using(exists(select 1 from public.active_trips t where t.id=trip_id and t.user_id=auth.uid())) with check(exists(select 1 from public.active_trips t where t.id=trip_id and t.user_id=auth.uid()));
revoke all on public.trusted_contacts,public.active_trips,public.trip_shares from anon;
